function renderStageBank(){
 const key=document.getElementById("stageSelect")?.value||"educacao_infantil";
 const q=(document.getElementById("stageSearch")?.value||"").toLowerCase();
 const d=PEDAGOGICAL_DB[key], box=document.getElementById("stageBank"); if(!box||!d)return;
 const plans=(d.plans||[]).filter(p=>(p.title+" "+p.axis+" "+p.objective+" "+p.activity).toLowerCase().includes(q));
 box.innerHTML=`<div class="stagehero"><h3>${escapeHtml(d.label)}</h3><p><strong>Focos:</strong> ${d.focus.map(escapeHtml).join(" • ")}</p></div>`+
 (plans.length?plans.map((p,i)=>`<div class="planmini"><h3>${i+1}. ${escapeHtml(p.title)}</h3><p><span class="badge">${escapeHtml(p.axis)}</span></p><p><strong>Objetivo:</strong> ${escapeHtml(p.objective)}</p><p><strong>Atividade:</strong> ${escapeHtml(p.activity)}</p><p><strong>Avaliação:</strong> ${escapeHtml(p.assessment)}</p><button class="primary" onclick="loadMiniPlan(${JSON.stringify(p.title)},${JSON.stringify(d.label)},${JSON.stringify(p.axis)},${JSON.stringify(p.objective)},${JSON.stringify(p.activity)},${JSON.stringify(p.assessment)})">📝 Levar para Plano de Aula</button></div>`).join(""):'<div class="card">Nenhum resultado para a busca.</div>');
}
function loadMiniPlan(title,stage,axis,obj,activity,assessment){
 document.getElementById("pEtapa").value=stage;
 document.getElementById("pEixo").value=axis;
 document.getElementById("pTema").value=title;
 document.getElementById("pObj").value=obj;
 document.getElementById("pProblema").value="Como resolver o desafio proposto na atividade: "+title+"?";
 document.getElementById("pMet").value=activity;
 document.getElementById("pAval").value=assessment;
 go("planos");
}
