function renderDisciplineBank(){
 const stage=document.getElementById("discStage")?.value||"EI";
 const disc=document.getElementById("discName")?.value||"";
 const q=(document.getElementById("discSearch")?.value||"").toLowerCase();
 const box=document.getElementById("disciplineBank");if(!box)return;
 const row=DISCIPLINE_DB[stage]; if(!row)return;
 const items=row.disciplinas.filter(x=>(!disc||x.disciplina===disc)&&(x.disciplina+" "+x.temas.join(" ")+" "+x.atividade+" "+x.objetivo).toLowerCase().includes(q));
 box.innerHTML=`<div class="stagehero"><h3>${escapeHtml(row.ano)}</h3><p>Integração com Computação: pensamento computacional, mundo digital e cultura digital.</p></div>`+
 (items.length?items.map((x,i)=>`<div class="disc-card"><h3>${i+1}. ${escapeHtml(x.disciplina)}</h3><div class="disc-tags">${x.temas.map(t=>`<span class="disc-tag">${escapeHtml(t)}</span>`).join("")}</div><p><strong>Objetivo:</strong> ${escapeHtml(x.objetivo)}</p><p><strong>Atividade:</strong> ${escapeHtml(x.atividade)}</p><p><strong>Produto:</strong> ${escapeHtml(x.produto)}</p><p><strong>Avaliação:</strong> ${escapeHtml(x.avaliacao)}</p><button class="primary" onclick="sendDisciplineToPlan(${JSON.stringify(x.disciplina)},${JSON.stringify(row.ano)},${JSON.stringify(x.temas.join(', '))},${JSON.stringify(x.objetivo)},${JSON.stringify(x.atividade)},${JSON.stringify(x.avaliacao)})">📝 Usar no Plano de Aula</button></div>`).join(""):'<div class="card">Nenhum resultado encontrado.</div>');
}
function sendDisciplineToPlan(disc,stage,tema,obj,atividade,avaliacao){
 document.getElementById("pEtapa").value=stage;
 document.getElementById("pTema").value=disc+" — "+tema;
 document.getElementById("pObj").value=obj;
 document.getElementById("pMet").value=atividade;
 document.getElementById("pAval").value=avaliacao;
 go("planos");
}
renderDisciplineBank();

