function renderResources(){
 const type=document.getElementById("resourceType")?.value||"sequencias",q=(document.getElementById("resourceSearch")?.value||"").toLowerCase(),box=document.getElementById("resourceBank");if(!box)return;
 const arr=(RESOURCES_DB[type]||[]).filter(x=>JSON.stringify(x).toLowerCase().includes(q));
 box.innerHTML=arr.length?arr.map(x=>{
  let body="";
  for(const [k,v] of Object.entries(x)){if(k==="titulo")continue;
    if(Array.isArray(v)) body+=`<p><strong>${escapeHtml(k)}:</strong></p><ul>${v.map(i=>`<li>${escapeHtml(i)}</li>`).join("")}</ul>`;
    else body+=`<p><strong>${escapeHtml(k)}:</strong> ${escapeHtml(v)}</p>`;
  }
  return `<div class="resource-card"><h3>${escapeHtml(x.titulo)}</h3>${body}<button class="primary" onclick="copyResource(${JSON.stringify(x.titulo)},${JSON.stringify(JSON.stringify(x,null,2))})">📋 Copiar conteúdo</button></div>`;
 }).join(""):'<div class="card">Nenhum recurso encontrado.</div>';
}
function copyResource(title,text){
 navigator.clipboard?.writeText(text).then(()=>alert("Recurso copiado: "+title)).catch(()=>prompt("Copie o conteúdo:",text));
}
