function shuffleArr(a){const x=[...a];for(let i=x.length-1;i>0;i--){const r=Math.floor(Math.random()*(i+1));[x[i],x[r]]=[x[r],x[i]]}return x}
function buildQuestions(d){
 const bank=cvQuestionBank[d.disc]||cvQuestionBank["Tecnologia/Informática"];
 const selected=shuffleArr(bank).slice(0,Math.min(d.qtd,bank.length));
 return selected.map((q,i)=>{
   const opts=shuffleArr([{t:q[1],c:true},{t:q[2],c:false},{t:q[3],c:false},{t:q[4],c:false}]);
   const letters=["A","B","C","D"];
   return {n:i+1,text:q[0],opts:opts.map((o,k)=>({letter:letters[k],text:o.t,correct:o.c}))};
 });
}
function assessmentData(){return {etapa:document.getElementById("avEtapa")?.value||"",bi:document.getElementById("avBi")?.value||"",disc:document.getElementById("avDisc")?.value||"",qtd:Number(document.getElementById("avQtd")?.value||10),tema:(document.getElementById("avTema")?.value||"").trim(),escola:(document.getElementById("avEscola")?.value||"").trim(),turma:(document.getElementById("avTurma")?.value||"").trim()}}
function generateAssessment(){
 const d=assessmentData();
 if(!d.tema){alert("Informe o tema ou conteúdo.");document.getElementById("avTema")?.focus();return}
 const questions=buildQuestions(d);
 const paper=`<div class="assessment-paper"><div class="assessment-header"><h3>${cvEsc(d.escola||"AVALIAÇÃO")}</h3><p><strong>${cvEsc(d.disc)}</strong> • ${cvEsc(d.etapa)} • ${cvEsc(d.bi)}</p><p>Tema: ${cvEsc(d.tema)}</p></div><div class="student-line"><div>Nome: <span style="width:75%"></span></div><div>Data: <span style="width:80px"></span></div><div>Turma: <span>${cvEsc(d.turma)}</span></div><div>Nota: <span style="width:80px"></span></div></div>${questions.map(q=>`<div class="question"><strong>${q.n}. ${cvEsc(q.text)}</strong><div class="options">${q.opts.map(o=>`<div>${o.letter}) ${cvEsc(o.text)}</div>`).join("")}</div></div>`).join("")}<p style="margin-top:24px;font-size:12px;color:#777">CARNEIROS VIRTUAL • Professor Antônio • carneirosvirtual.com</p></div>`;
 const key=`<div class="answer-key">${questions.map(q=>{const a=q.opts.find(o=>o.correct);return `<div class="key-item">${q.n} — ${a.letter}</div>`}).join("")}</div>`;
 const data={...d,questions,paper,key};
 const box=document.getElementById("assessmentOutput"); if(box){box.innerHTML=paper;box.dataset.assessment=JSON.stringify(data)}
 const ko=document.getElementById("answerKeyOutput");if(ko)ko.innerHTML=key;
 return data;
}
function saveAssessment(){
 const box=document.getElementById("assessmentOutput");let d;
 if(box?.dataset.assessment){try{d=JSON.parse(box.dataset.assessment)}catch(e){}}
 if(!d)d=generateAssessment(); if(!d)return;
 const arr=JSON.parse(localStorage.getItem("cv_assessments")||"[]");
 arr.unshift({id:Date.now(),...d});
 localStorage.setItem("cv_assessments",JSON.stringify(arr.slice(0,30)));
 renderSavedAssessments();alert("Avaliação salva neste computador.");
}
function renderSavedAssessments(){
 const el=document.getElementById("savedAssessments");if(!el)return;
 const arr=JSON.parse(localStorage.getItem("cv_assessments")||"[]");
 if(!arr.length){el.innerHTML='<span class="muted">Nenhuma avaliação salva.</span>';return}
 el.innerHTML=arr.map(x=>`<div class="saved-av"><div><strong>${cvEsc(x.tema)}</strong><br><small>${cvEsc(x.etapa)} • ${cvEsc(x.bi)} • ${cvEsc(x.disc)} • ${x.qtd} questões</small></div><div><button onclick="loadAssessment(${x.id})">Abrir</button><button onclick="deleteAssessment(${x.id})">Excluir</button></div></div>`).join("");
}
function loadAssessment(id){
 const x=JSON.parse(localStorage.getItem("cv_assessments")||"[]").find(a=>a.id===id);if(!x)return;
 [["avEtapa","etapa"],["avBi","bi"],["avDisc","disc"],["avQtd","qtd"],["avTema","tema"],["avEscola","escola"],["avTurma","turma"]].forEach(([a,b])=>{const e=document.getElementById(a);if(e)e.value=x[b]});
 const box=document.getElementById("assessmentOutput");if(box){box.innerHTML=x.paper;box.dataset.assessment=JSON.stringify(x)}
 const ko=document.getElementById("answerKeyOutput");if(ko)ko.innerHTML=x.key;
 document.getElementById("avaliacoes")?.scrollIntoView({behavior:"smooth"});
}
function deleteAssessment(id){localStorage.setItem("cv_assessments",JSON.stringify(JSON.parse(localStorage.getItem("cv_assessments")||"[]").filter(x=>x.id!==id)));renderSavedAssessments()}
function printAssessment(){
 const box=document.getElementById("assessmentOutput");if(!box?.dataset.assessment){if(!generateAssessment())return}
 const d=JSON.parse(document.getElementById("assessmentOutput").dataset.assessment);
 const w=window.open("","_blank");if(!w)return;
 w.document.write(`<html><head><title>Avaliação — Carneiros Virtual</title><style>@page{size:A4;margin:12mm}body{font-family:Arial,sans-serif;color:#222}.assessment-paper{max-width:100%;padding:10px}.assessment-header{text-align:center;border-bottom:2px solid #b98500;padding-bottom:10px}.student-line{display:grid;grid-template-columns:1fr 150px;gap:12px;margin:15px 0}.question{margin:14px 0;break-inside:avoid}.question strong{display:block}.options div{margin:4px 0}h3{color:#7d5909}</style></head><body>${d.paper}</body></html>`);w.document.close();w.focus();w.print();
}
function printAnswerKey(){
 const ko=document.getElementById("answerKeyOutput");if(!ko||!ko.innerHTML||ko.textContent.includes("aparecerá")){if(!generateAssessment())return}
 const html=document.getElementById("answerKeyOutput").innerHTML;
 const w=window.open("","_blank");if(!w)return;
 w.document.write(`<html><head><title>Gabarito — Carneiros Virtual</title><style>@page{size:A4;margin:15mm}body{font-family:Arial;padding:20px}.answer-key{display:grid;grid-template-columns:repeat(5,1fr);gap:10px}.key-item{border:1px solid #ccc;padding:10px;text-align:center}</style></head><body><h2>CARNEIROS VIRTUAL — GABARITO</h2>${html}<p>Professor Antônio • carneirosvirtual.com</p></body></html>`);w.document.close();w.focus();w.print();
}
function clearAssessment(){
 ["avTema","avEscola","avTurma"].forEach(id=>{const e=document.getElementById(id);if(e)e.value=""});
 const o=document.getElementById("assessmentOutput");if(o){o.innerHTML='<h3>Prévia da avaliação</h3><p class="muted">Escolha os campos e clique em <strong>Gerar avaliação</strong>.</p>';delete o.dataset.assessment}
 const k=document.getElementById("answerKeyOutput");if(k)k.innerHTML='<p class="muted">O gabarito aparecerá aqui após gerar a avaliação.</p>';
}
document.addEventListener("DOMContentLoaded",renderSavedAssessments);

/* ===== V20 — Banco de Questões e versões A/B/C ===== */
function renderQuestionPicker(){
 const el=document.getElementById("questionPicker"); if(!el)return;
 const disc=document.getElementById("bqDisc")?.value||"Tecnologia/Informática";
 const qtd=Number(document.getElementById("bqQtd")?.value||10);
 const bank=cvQuestionBank[disc]||[];
 const checked=JSON.parse(localStorage.getItem("cv_bq_selected_"+disc)||"[]");
 el.innerHTML=bank.map((q,i)=>`<div class="question-pick"><input type="checkbox" id="bq_${i}" ${checked.includes(i)?"checked":""} onchange="syncQuestionSelection()"><label for="bq_${i}"><strong>${i+1}.</strong> ${cvEsc(q[0])}<br><small>Resposta correta: ${cvEsc(q[1])}</small></label></div>`).join("");
 const hint=document.createElement("p");hint.className="muted";hint.textContent=`Selecione até ${qtd} questões. Se selecionar mais, as primeiras ${qtd} serão usadas.`;el.prepend(hint);
}
function syncQuestionSelection(){
 const disc=document.getElementById("bqDisc")?.value||"";
 const arr=[...document.querySelectorAll("#questionPicker input[type=checkbox]:checked")].map(x=>Number(x.id.split("_")[1]));
 localStorage.setItem("cv_bq_selected_"+disc,JSON.stringify(arr));
}
function selectedQuestions(){
 const disc=document.getElementById("bqDisc")?.value||"";
 const qtd=Number(document.getElementById("bqQtd")?.value||10);
 const bank=cvQuestionBank[disc]||[];
 let ids=[...document.querySelectorAll("#questionPicker input[type=checkbox]:checked")].map(x=>Number(x.id.split("_")[1]));
 if(!ids.length) ids=shuffleArr(bank.map((_,i)=>i)).slice(0,qtd);
 ids=ids.slice(0,qtd);
 return ids.map(i=>bank[i]).filter(Boolean);
}
function makeVersion(raw,seed){
 let qs=raw.map(q=>({text:q[0],opts:shuffleArr([q[1],q[2],q[3],q[4]]).map((text,i)=>({letter:["A","B","C","D"][i],text,correct:text===q[1]}))}));
 qs=shuffleArr(qs);
 return qs.map((q,i)=>({...q,n:i+1}));
}
function versionPaper(v,d){
 return `<div class="version-paper"><div class="version-mark">VERSÃO ${v}</div><h3>${cvEsc(d.escola||"CARNEIROS VIRTUAL")}</h3><p style="text-align:center"><strong>${cvEsc(d.disc)}</strong> • ${cvEsc(d.etapa)} • ${cvEsc(d.bi)}${d.tema?` • ${cvEsc(d.tema)}`:""}</p><p>Nome: ________________________________________________ &nbsp;&nbsp; Data: ____/____/______</p><p>Turma: ______________________________</p>${d.qs.map(q=>`<div class="question"><strong>${q.n}. ${cvEsc(q.text)}</strong><div class="options">${q.opts.map(o=>`<div>${o.letter}) ${cvEsc(o.text)}</div>`).join("")}</div></div>`).join("")}<p style="font-size:11px;color:#777;margin-top:25px">CARNEIROS VIRTUAL • Professor Antônio • carneirosvirtual.com</p></div>`;
}
function versionKey(v,qs){
 return `<div class="version-paper"><h3>GABARITO — VERSÃO ${v}</h3><div class="answer-key">${qs.map(q=>`<div class="key-item">${q.n} — ${q.opts.find(o=>o.correct)?.letter||""}</div>`).join("")}</div></div>`;
}
function generateVersions(){
 const raw=selectedQuestions(); if(!raw.length){alert("Não há questões disponíveis.");return}
 const d={etapa:document.getElementById("bqEtapa")?.value||"",bi:document.getElementById("bqBi")?.value||"",disc:document.getElementById("bqDisc")?.value||"",tema:(document.getElementById("bqTema")?.value||"").trim(),escola:"CARNEIROS VIRTUAL"};
 const versions={A:makeVersion(raw,1),B:makeVersion(raw,2),C:makeVersion(raw,3)};
 const all={d,versions};
 document.getElementById("versionsOutput").dataset.versions=JSON.stringify(all);
 document.getElementById("versionsOutput").innerHTML=`<div class="version-tabs"><button class="version-tab active" onclick="showVersion('A')">Versão A</button><button class="version-tab" onclick="showVersion('B')">Versão B</button><button class="version-tab" onclick="showVersion('C')">Versão C</button><button class="version-tab" onclick="showVersion('G')">Gabaritos</button></div><div id="versionDisplay">${versionPaper("A",{...d,qs:versions.A})}</div>`;
}
function showVersion(v){
 const box=document.getElementById("versionsOutput");if(!box?.dataset.versions){generateVersions();return}
 const all=JSON.parse(box.dataset.versions);let html="";
 if(v==="G") html=versionKey("A",all.versions.A)+versionKey("B",all.versions.B)+versionKey("C",all.versions.C);
 else html=versionPaper(v,{...all.d,qs:all.versions[v]});
 document.getElementById("versionDisplay").innerHTML=html;
 document.querySelectorAll(".version-tab").forEach(x=>x.classList.remove("active"));
 [...document.querySelectorAll(".version-tab")].find(x=>x.textContent.includes(v==="G"?"Gabaritos":"Versão "+v))?.classList.add("active");
}
function printVersion(v){
 const box=document.getElementById("versionsOutput");if(!box?.dataset.versions){generateVersions();return}
 const all=JSON.parse(document.getElementById("versionsOutput").dataset.versions);
 let html="";
 if(v==="G") html=versionKey("A",all.versions.A)+versionKey("B",all.versions.B)+versionKey("C",all.versions.C);
 else html=versionPaper(v,{...all.d,qs:all.versions[v]});
 const w=window.open("","_blank");if(!w)return;
 w.document.write(`<html><head><title>Carneiros Virtual — ${v==="G"?"Gabaritos":"Versão "+v}</title><style>@page{size:A4;margin:12mm}body{font-family:Arial;color:#222}.version-paper{page-break-after:always}.question{margin:13px 0;break-inside:avoid}.options div{margin:4px 0}.answer-key{display:grid;grid-template-columns:repeat(5,1fr);gap:8px}.key-item{border:1px solid #bbb;padding:8px;text-align:center}</style></head><body>${html}</body></html>`);
 w.document.close();w.focus();w.print();
}
