/* =========================================================
   CARNEIROS VIRTUAL V24 — SISTEMA AVANÇADO DE AVALIAÇÕES
   ========================================================= */
(function(){
  const KEY="cv_avaliacoes_v24";
  const $=id=>document.getElementById(id);
  const qs=()=>window.CV_QUESTOES_BIMESTRAIS || [];

  function allQuestions(){
    const b=qs();
    if(Array.isArray(b)) return b;
    const out=[];
    Object.keys(b).forEach(k=>{
      const arr=b[k];
      if(Array.isArray(arr)) out.push(...arr);
    });
    return out;
  }

  function getYears(){
    const set=[...new Set(allQuestions().map(q=>q.ano||q.etapa||""))].filter(Boolean);
    return set.length?set:["EI","1º","2º","3º","4º","5º","6º","7º","8º","9º"];
  }
  function getDisc(){
    const set=[...new Set(allQuestions().map(q=>q.disciplina||""))].filter(Boolean);
    return set.length?set:["Português","Matemática","Ciências","História","Geografia","Arte","Educação Física","Ensino Religioso","Inglês","Tecnologia/Informática"];
  }

  function esc(s){return String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]));}
  function shuffle(a){return a.map(v=>[Math.random(),v]).sort((x,y)=>x[0]-y[0]).map(x=>x[1]);}
  function read(){try{return JSON.parse(localStorage.getItem(KEY)||"[]")}catch(e){return[]}}
  function write(x){localStorage.setItem(KEY,JSON.stringify(x))}

  window.cvV24CreateUI=function(){
    if($("avaliacoesV24")) return;
    const sec=document.createElement("section");
    sec.id="avaliacoesV24";
    sec.className="page-section";
    sec.innerHTML=`
      <div class="card">
        <h2>🧾 Sistema Avançado de Avaliações</h2>
        <p>Crie provas automaticamente por etapa, bimestre, disciplina, dificuldade e turma. As versões A, B e C podem ser diferentes.</p>
        <div class="grid">
          <label>Etapa/Ano<select id="v24Ano">${getYears().map(x=>`<option>${esc(x)}</option>`).join("")}</select></label>
          <label>Bimestre<select id="v24Bim"><option>1º Bimestre</option><option>2º Bimestre</option><option>3º Bimestre</option><option>4º Bimestre</option></select></label>
          <label>Disciplina<select id="v24Disc">${getDisc().map(x=>`<option>${esc(x)}</option>`).join("")}</select></label>
          <label>Quantidade<select id="v24Qtd"><option>10</option><option>15</option><option>20</option><option>25</option></select></label>
          <label>Dificuldade<select id="v24Dif"><option value="">Todas</option><option>Fácil</option><option>Médio</option><option>Difícil</option></select></label>
          <label>Escola<input id="v24Esc" placeholder="Nome da escola"></label>
          <label>Turma<input id="v24Turma" placeholder="Ex.: 5º Ano A"></label>
          <label>Professor(a)<input id="v24Prof" placeholder="Nome do professor"></label>
        </div>
        <div class="actions">
          <button class="btn primary" onclick="cvV24Generate()">🎲 Gerar 3 versões</button>
          <button class="btn" onclick="cvV24Save()">💾 Salvar avaliação</button>
          <button class="btn" onclick="cvV24List()">📚 Avaliações salvas</button>
          <button class="btn" onclick="cvV24Print('A')">🖨️ Imprimir A</button>
          <button class="btn" onclick="cvV24Print('B')">🖨️ Imprimir B</button>
          <button class="btn" onclick="cvV24Print('C')">🖨️ Imprimir C</button>
          <button class="btn" onclick="cvV24Print('G')">🔑 Imprimir gabaritos</button>
        </div>
        <div id="v24Info"></div>
        <div id="v24Preview"></div>
      </div>`;
    document.body.appendChild(sec);
  };

  function filtered(){
    const ano=$("v24Ano")?.value, bim=$("v24Bim")?.value, disc=$("v24Disc")?.value, dif=$("v24Dif")?.value;
    return allQuestions().filter(q=>{
      const qb=q.bimestre||q.bim||"";
      return (!ano || String(q.ano||q.etapa||"")===ano) &&
             (!disc || String(q.disciplina||"")===disc) &&
             (!dif || String(q.dificuldade||"")===dif) &&
             (!qb || qb===bim || qb===bim.replace(" Bimestre",""));
    });
  }

  function normalize(q){
    const opts=q.alternativas || q.opcoes || [];
    return {
      id:q.id||crypto.randomUUID?.()||String(Date.now()+Math.random()),
      questao:q.questao||q.pergunta||"",
      alternativas:opts,
      gabarito:q.gabarito ?? q.correta ?? 0,
      dificuldade:q.dificuldade||"Médio",
      tema:q.tema||"",
      justificativa:q.justificativa||"",
      objetivo_pedagogico:q.objetivo_pedagogico||"",
      habilidade_sugerida:q.habilidade_sugerida||""
    };
  }

  window.cvV24Generate=function(){
    const base=filtered().map(normalize);
    const qtd=Number($("v24Qtd")?.value||10);
    if(base.length<qtd){
      $("v24Info").innerHTML=`<div class="alert">Foram encontradas apenas <b>${base.length}</b> questões para os filtros escolhidos.</div>`;
      return;
    }
    const escolhidas=shuffle(base).slice(0,qtd);
    const versions={};
    ["A","B","C"].forEach((letter,i)=>{
      versions[letter]=shuffle(escolhidas).map(q=>{
        const indexed=q.alternativas.map((text,idx)=>({text,idx}));
        const opts=shuffle(indexed);
        return {...q, alternativas:opts.map(x=>x.text), gabarito:opts.findIndex(x=>x.idx===q.gabarito)};
      });
    });
    window.cvV24Current={
      id:"AV-"+Date.now(), ano:$("v24Ano").value,bimestre:$("v24Bim").value,
      disciplina:$("v24Disc").value, quantidade:qtd,dificuldade:$("v24Dif").value,
      escola:$("v24Esc").value,turma:$("v24Turma").value,professor:$("v24Prof").value,
      versions, createdAt:new Date().toLocaleString("pt-BR")
    };
    $("v24Info").innerHTML=`<div class="success">✔ Avaliação gerada: <b>${qtd} questões</b> × 3 versões. Cada versão possui ordem de questões e alternativas embaralhadas.</div>`;
    cvV24Render();
  };

  function paper(letter){
    const d=window.cvV24Current, arr=d.versions[letter];
    if(!arr) return "";
    let h=`<div class="v24-paper"><header><h1>${esc(d.escola||"CARNEIROS VIRTUAL")}</h1>
      <h2>AVALIAÇÃO — ${esc(d.disciplina)}</h2>
      <p>${esc(d.ano)} • ${esc(d.bimestre)} • Versão ${letter}</p>
      <p>Aluno(a): ________________________________________________</p>
      <p>Turma: ${esc(d.turma)} &nbsp;&nbsp; Professor(a): ${esc(d.professor)}</p></header>`;
    arr.forEach((q,i)=>{
      h+=`<div class="v24-q"><b>${i+1}. ${esc(q.questao)}</b>`;
      q.alternativas.forEach((a,j)=>h+=`<div>${String.fromCharCode(65+j)}) ${esc(a)}</div>`);
      h+=`</div>`;
    });
    return h+`<footer>CarneirosVirtual.com • Professor Antônio</footer></div>`;
  }

  function gabaritos(){
    const d=window.cvV24Current;
    return ["A","B","C"].map(l=>{
      const a=d.versions[l];
      return `<div class="v24-g"><h2>GABARITO — VERSÃO ${l}</h2>`+
        a.map((q,i)=>`${i+1}. <b>${String.fromCharCode(65+q.gabarito)}</b>`).join(" &nbsp; | &nbsp; ")+"</div>";
    }).join("");
  }

  function cvV24Render(){
    const d=window.cvV24Current;
    $("v24Preview").innerHTML=`<div class="tabs"><button class="btn" onclick="document.getElementById('v24Show').innerHTML=cvV24Paper('A')">Versão A</button><button class="btn" onclick="document.getElementById('v24Show').innerHTML=cvV24Paper('B')">Versão B</button><button class="btn" onclick="document.getElementById('v24Show').innerHTML=cvV24Paper('C')">Versão C</button><button class="btn" onclick="document.getElementById('v24Show').innerHTML=cvV24G()">Gabaritos</button></div><div id="v24Show">${paper("A")}</div>`;
  }
  window.cvV24Paper=l=>paper(l);
  window.cvV24G=()=>gabaritos();

  window.cvV24Save=function(){
    if(!window.cvV24Current){alert("Gere uma avaliação primeiro.");return}
    const a=read(); a.push(window.cvV24Current); write(a);
    $("v24Info").innerHTML=`<div class="success">✔ Avaliação ${window.cvV24Current.id} salva neste computador.</div>`;
  };

  window.cvV24List=function(){
    const a=read();
    if(!a.length){alert("Nenhuma avaliação salva.");return}
    const html=a.map((x,i)=>`<div class="card"><b>${esc(x.id)}</b> — ${esc(x.ano)} — ${esc(x.disciplina)} — ${esc(x.bimestre)} — ${x.quantidade} questões<br><button class="btn" onclick='window.cvV24Current=${JSON.stringify(x).replace(/'/g,"&#39;")};cvV24Render()'>Abrir</button> <button class="btn" onclick="cvV24Delete(${i})">Excluir</button></div>`).join("");
    $("v24Preview").innerHTML=html;
  };
  window.cvV24Delete=function(i){const a=read();a.splice(i,1);write(a);cvV24List()};

  window.cvV24Print=function(letter){
    if(!window.cvV24Current){alert("Gere ou abra uma avaliação primeiro.");return}
    let body=letter==="G"?gabaritos():paper(letter);
    const w=window.open("","_blank");
    if(!w)return;
    w.document.write(`<html><head><title>Carneiros Virtual — Avaliação</title><style>
      @page{size:A4 portrait;margin:12mm}body{font-family:Arial,sans-serif;color:#111}
      .v24-paper{page-break-after:always}.v24-q{margin:14px 0;line-height:1.5}
      header{text-align:center;border-bottom:2px solid #222;padding-bottom:10px}footer{text-align:center;margin-top:25px;font-size:11px}
      .v24-g{page-break-after:always;font-size:18px;line-height:2}
    </style></head><body>${body}</body></html>`);
    w.document.close();w.focus();setTimeout(()=>w.print(),300);
  };

  // botão no menu
  function addNav(){
    const nav=$("nav")||document.querySelector(".nav");
    if(nav && !document.getElementById("navV24")){
      const b=document.createElement("button");b.id="navV24";b.className="nav-btn";b.textContent="🧾 • Sistema de Avaliações";
      b.onclick=()=>{cvV24CreateUI();document.querySelectorAll("section").forEach(s=>s.style.display="none");$("avaliacoesV24").style.display="block";$("avaliacoesV24").scrollIntoView()};
      nav.appendChild(b);
    }
  }
  document.addEventListener("DOMContentLoaded",()=>setTimeout(addNav,400));
})();


/* =========================================================
   CARNEIROS VIRTUAL V25 — GESTÃO ESCOLAR INTEGRADA
   Escola → Turma → Professor → Alunos → Avaliações → Notas → Resultados
   100% local/offline via localStorage
   ========================================================= */
(function(){
 const KEY="cv_gestao_v25";
 const $=id=>document.getElementById(id);
 const esc=s=>String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]));
 function load(){try{return JSON.parse(localStorage.getItem(KEY)||'{"escolas":[],"professores":[],"turmas":[],"alunos":[],"avaliacoes":[],"notas":[]}')}catch(e){return {escolas:[],professores:[],turmas:[],alunos:[],avaliacoes:[],notas:[]}}}
 function save(d){localStorage.setItem(KEY,JSON.stringify(d))}
 function id(p){return p+"-"+Date.now()+"-"+Math.random().toString(36).slice(2,7)}
 function val(x){return ($(x)?.value||"").trim()}

 window.cvV25UI=function(){
  if($("gestaoV25")) return;
  const s=document.createElement("section"); s.id="gestaoV25"; s.className="page-section";
  s.innerHTML=`
  <div class="card">
   <h2>🏫 Gestão Escolar Integrada</h2>
   <p>Cadastre a estrutura escolar e acompanhe avaliações, notas e resultados. Os dados ficam salvos neste computador.</p>
   <div class="v25-tabs">
    <button class="btn primary" onclick="cvV25Tab('dash')">📊 Painel</button>
    <button class="btn" onclick="cvV25Tab('escola')">🏫 Escolas</button>
    <button class="btn" onclick="cvV25Tab('prof')">👨‍🏫 Professores</button>
    <button class="btn" onclick="cvV25Tab('turma')">👥 Turmas</button>
    <button class="btn" onclick="cvV25Tab('aluno')">🧑‍🎓 Alunos</button>
    <button class="btn" onclick="cvV25Tab('nota')">📝 Notas</button>
    <button class="btn" onclick="cvV25Tab('resultado')">📈 Resultados</button>
    <button class="btn" onclick="cvV25Export()">⬇️ Exportar dados</button>
   </div>
   <div id="v25Content"></div>
  </div>`;
  document.body.appendChild(s); cvV25Tab("dash");
 };

 function options(arr, text){return arr.map(x=>`<option value="${esc(x.id)}">${esc(x[text]||x.nome)}</option>`).join("")}

 window.cvV25Tab=function(tab){
  const d=load(), c=$("v25Content"); if(!c)return;
  if(tab==="dash"){
   c.innerHTML=`<div class="v25-stats">
    <div><b>${d.escolas.length}</b><span>Escolas</span></div>
    <div><b>${d.professores.length}</b><span>Professores</span></div>
    <div><b>${d.turmas.length}</b><span>Turmas</span></div>
    <div><b>${d.alunos.length}</b><span>Alunos</span></div>
    <div><b>${d.avaliacoes.length}</b><span>Avaliações</span></div>
    <div><b>${d.notas.length}</b><span>Notas</span></div>
   </div>
   <div class="card"><h3>Fluxo recomendado</h3><ol><li>Cadastre a escola.</li><li>Cadastre professores.</li><li>Crie as turmas.</li><li>Cadastre os alunos.</li><li>Registre avaliações.</li><li>Lance as notas.</li><li>Consulte os resultados.</li></ol></div>`;
  }
  if(tab==="escola") c.innerHTML=`
   <h3>🏫 Cadastro de escola</h3><div class="grid">
   <label>Nome<input id="eNome"></label><label>INEP/Código<input id="eCod"></label><label>Município<input id="eMun" value="Carneiros - AL"></label></div>
   <button class="btn primary" onclick="cvV25Add('escola')">Adicionar escola</button>${table(d.escolas,["nome","codigo","municipio"],"escola")}`;
  if(tab==="prof") c.innerHTML=`
   <h3>👨‍🏫 Cadastro de professor</h3><div class="grid">
   <label>Nome<input id="pNome"></label><label>CPF/Matrícula<input id="pMat"></label><label>Disciplina<input id="pDisc"></label></div>
   <button class="btn primary" onclick="cvV25Add('prof')">Adicionar professor</button>${table(d.professores,["nome","matricula","disciplina"],"prof")}`;
  if(tab==="turma") c.innerHTML=`
   <h3>👥 Cadastro de turma</h3><div class="grid">
   <label>Nome da turma<input id="tNome" placeholder="Ex.: 5º Ano A"></label>
   <label>Ano/Etapa<input id="tAno" placeholder="Ex.: 5º Ano"></label>
   <label>Turno<input id="tTurno" placeholder="Manhã / Tarde / Integral"></label>
   <label>Escola<select id="tEsc"><option value="">Selecione</option>${options(d.escolas,"nome")}</select></label>
   <label>Professor<select id="tProf"><option value="">Selecione</option>${options(d.professores,"nome")}</select></label></div>
   <button class="btn primary" onclick="cvV25Add('turma')">Adicionar turma</button>${table(d.turmas,["nome","ano","turno","escola","professor"],"turma")}`;
  if(tab==="aluno") c.innerHTML=`
   <h3>🧑‍🎓 Cadastro de aluno</h3><div class="grid">
   <label>Nome<input id="aNome"></label><label>Matrícula<input id="aMat"></label>
   <label>Turma<select id="aTurma"><option value="">Selecione</option>${options(d.turmas,"nome")}</select></label></div>
   <button class="btn primary" onclick="cvV25Add('aluno')">Adicionar aluno</button>${table(d.alunos,["nome","matricula","turma"],"aluno")}`;
  if(tab==="nota") c.innerHTML=`
   <h3>📝 Lançamento de notas</h3><div class="grid">
   <label>Aluno<select id="nAluno"><option value="">Selecione</option>${options(d.alunos,"nome")}</select></label>
   <label>Disciplina<input id="nDisc"></label><label>Bimestre<select id="nBim"><option>1º Bimestre</option><option>2º Bimestre</option><option>3º Bimestre</option><option>4º Bimestre</option></select></label>
   <label>Nota (0–10)<input id="nNota" type="number" min="0" max="10" step="0.1"></label>
   <label>Frequência (%)<input id="nFreq" type="number" min="0" max="100" step="1" value="100"></label></div>
   <button class="btn primary" onclick="cvV25Add('nota')">Lançar nota</button>${table(d.notas,["aluno","disciplina","bimestre","nota","frequencia"],"nota")}`;
  if(tab==="resultado"){
   c.innerHTML=`<h3>📈 Resultado por aluno</h3><div class="grid"><label>Aluno<select id="rAluno"><option value="">Todos</option>${options(d.alunos,"nome")}</select></label></div>
   <button class="btn primary" onclick="cvV25Result()">Gerar resultado</button><div id="v25Result"></div>`;
  }
 };

 function table(arr,fields,type){
  if(!arr.length)return `<p class="muted">Nenhum registro cadastrado.</p>`;
  const labels={nome:"Nome",codigo:"Código",municipio:"Município",matricula:"Matrícula",disciplina:"Disciplina",ano:"Ano",turno:"Turno",escola:"Escola",professor:"Professor",turma:"Turma",bimestre:"Bimestre",nota:"Nota",frequencia:"Frequência"};
  return `<div class="v25-table"><table><thead><tr>${fields.map(f=>`<th>${labels[f]||f}</th>`).join("")}<th>Ação</th></tr></thead><tbody>${arr.map(x=>`<tr>${fields.map(f=>`<td>${esc(resolve(x[f],f))}</td>`).join("")}<td><button class="btn small" onclick="cvV25Del('${type}','${x.id}')">Excluir</button></td></tr>`).join("")}</tbody></table></div>`;
 }
 function resolve(v,f){
  const d=load();
  if(["escola","professor","turma","aluno"].includes(f)&&v){
   const list=f==="escola"?d.escolas:f==="professor"?d.professores:f==="turma"?d.turmas:d.alunos;
   return list.find(x=>x.id===v)?.nome||v;
  }
  return v;
 }

 window.cvV25Add=function(type){
  const d=load(), x={id:id(type)};
  if(type==="escola"){x.nome=val("eNome");x.codigo=val("eCod");x.municipio=val("eMun");d.escolas.push(x)}
  if(type==="prof"){x.nome=val("pNome");x.matricula=val("pMat");x.disciplina=val("pDisc");d.professores.push(x)}
  if(type==="turma"){x.nome=val("tNome");x.ano=val("tAno");x.turno=val("tTurno");x.escola=val("tEsc");x.professor=val("tProf");d.turmas.push(x)}
  if(type==="aluno"){x.nome=val("aNome");x.matricula=val("aMat");x.turma=val("aTurma");d.alunos.push(x)}
  if(type==="nota"){let n=Number(val("nNota"));if(isNaN(n)||n<0||n>10){alert("Informe uma nota entre 0 e 10.");return}x.aluno=val("nAluno");x.disciplina=val("nDisc");x.bimestre=val("nBim");x.nota=n;x.frequencia=Number(val("nFreq")||0);d.notas.push(x)}
  save(d); cvV25Tab(type==="prof"?"prof":type==="escola"?"escola":type==="turma"?"turma":type==="aluno"?"aluno":"nota");
 };
 window.cvV25Del=function(type,ident){
  const d=load(), map={escola:"escolas",prof:"professores",turma:"turmas",aluno:"alunos",nota:"notas"};
  d[map[type]]=d[map[type]].filter(x=>x.id!==ident);save(d);cvV25Tab(type==="prof"?"prof":type);
 };

 window.cvV25Result=function(){
  const d=load(), aid=val("rAluno"), rows=d.notas.filter(n=>!aid||n.aluno===aid);
  if(!rows.length){$("v25Result").innerHTML="<p>Nenhuma nota lançada.</p>";return}
  const groups={};
  rows.forEach(n=>{const k=n.aluno+"|"+n.disciplina;(groups[k]??=[]).push(n)});
  let html=`<div class="v25-table"><table><thead><tr><th>Aluno</th><th>Disciplina</th><th>Média</th><th>Frequência média</th><th>Situação</th></tr></thead><tbody>`;
  Object.values(groups).forEach(a=>{const n=a[0],avg=a.reduce((s,x)=>s+x.nota,0)/a.length,fr=a.reduce((s,x)=>s+x.frequencia,0)/a.length;
    html+=`<tr><td>${esc(resolve(n.aluno,"aluno"))}</td><td>${esc(n.disciplina)}</td><td>${avg.toFixed(1)}</td><td>${fr.toFixed(0)}%</td><td><b>${avg>=6&&fr>=75?"APTO":"EM ACOMPANHAMENTO"}</b></td></tr>`});
  $("v25Result").innerHTML=html+"</tbody></table></div>";
 };
 window.cvV25Export=function(){
  const blob=new Blob([JSON.stringify(load(),null,2)],{type:"application/json"});
  const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="carneiros_virtual_dados_gestao_v25.json";a.click();
 };
 function nav(){
  const n=$("nav")||document.querySelector(".nav");if(n&&!$("navV25")){
   const b=document.createElement("button");b.id="navV25";b.className="nav-btn";b.textContent="🏫 • Gestão Escolar";
   b.onclick=()=>{cvV25UI();document.querySelectorAll("section").forEach(s=>s.style.display="none");$("gestaoV25").style.display="block"};
   n.appendChild(b);
  }
 }
 document.addEventListener("DOMContentLoaded",()=>setTimeout(nav,500));
})();


/* =========================================================
   V26 — CORREÇÃO DO SISTEMA AVANÇADO DE QUESTÕES
   Corrige a leitura do banco hierárquico:
   Ano -> Disciplina -> Bimestre -> 50 questões
   ========================================================= */
(function(){
  const originalCreate = window.cvV24CreateUI;
  const $=id=>document.getElementById(id);
  function bank(){ return window.CV_QUESTOES_BIMESTRAIS || {}; }

  function allQuestions(){
    const out=[];
    const b=bank();
    Object.keys(b).forEach(ano=>{
      const disciplinas=b[ano]||{};
      Object.keys(disciplinas).forEach(disc=>{
        const bims=disciplinas[disc]||{};
        Object.keys(bims).forEach(bim=>{
          const arr=bims[bim];
          if(Array.isArray(arr)) arr.forEach(q=>out.push({...q,ano,disciplina:disc,bimestre:bim}));
        });
      });
    });
    return out;
  }
  function years(){return Object.keys(bank())}
  function discs(){
    const s=new Set();
    years().forEach(y=>Object.keys(bank()[y]||{}).forEach(d=>s.add(d)));
    return [...s];
  }
  function esc(s){return String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]))}
  function shuffle(a){return a.map(x=>[Math.random(),x]).sort((a,b)=>a[0]-b[0]).map(x=>x[1])}
  function filtered(){
    const ano=$("v24Ano")?.value||years()[0];
    const bim=$("v24Bim")?.value||"1º bimestre";
    const disc=$("v24Disc")?.value||discs()[0];
    const dif=$("v24Dif")?.value||"";
    return allQuestions().filter(q=>
      q.ano===ano && q.disciplina===disc && q.bimestre===bim &&
      (!dif || q.dificuldade===dif)
    );
  }
  function normalize(q){
    const opts=q.alternativas||[];
    const gi=typeof q.gabarito==="number" ? q.gabarito : opts.indexOf(q.gabarito);
    return {id:q.id,questao:q.questao,alternativas:opts,gabarito:gi<0?0:gi,
      dificuldade:q.dificuldade,tema:q.tema,justificativa:q.justificativa,
      objetivo_pedagogico:q.objetivo_pedagogico,habilidade_sugerida:q.habilidade_sugerida};
  }
  window.cvV24CreateUI=function(){
    if($("avaliacoesV24")) return;
    const sec=document.createElement("section");
    sec.id="avaliacoesV24"; sec.className="page-section";
    sec.innerHTML=`
      <div class="card">
        <h2>🧾 Sistema Avançado de Avaliações</h2>
        <p>Banco integrado por <b>Ano + Disciplina + Bimestre</b>. São 50 questões disponíveis em cada combinação.</p>
        <div class="grid">
          <label>Etapa/Ano<select id="v24Ano">${years().map(x=>`<option>${esc(x)}</option>`).join("")}</select></label>
          <label>Bimestre<select id="v24Bim"><option>1º bimestre</option><option>2º bimestre</option><option>3º bimestre</option><option>4º bimestre</select></label>
          <label>Disciplina<select id="v24Disc">${discs().map(x=>`<option>${esc(x)}</option>`).join("")}</select></label>
          <label>Quantidade<select id="v24Qtd"><option>10</option><option>15</option><option>20</option><option>25</option></select></label>
          <label>Dificuldade<select id="v24Dif"><option value="">Todas</option><option>Fácil</option><option>Médio</option><option>Difícil</option></select></label>
          <label>Escola<input id="v24Esc" placeholder="Nome da escola"></label>
          <label>Turma<input id="v24Turma" placeholder="Ex.: 5º Ano A"></label>
          <label>Professor(a)<input id="v24Prof" placeholder="Nome do professor"></label>
        </div>
        <div id="v26BankStatus" class="success"></div>
        <div class="actions">
          <button class="btn primary" onclick="cvV26Generate()">🎲 Gerar 3 versões</button>
          <button class="btn" onclick="cvV26Save()">💾 Salvar avaliação</button>
          <button class="btn" onclick="cvV26List()">📚 Avaliações salvas</button>
          <button class="btn" onclick="cvV26Print('A')">🖨️ Imprimir A</button>
          <button class="btn" onclick="cvV26Print('B')">🖨️ Imprimir B</button>
          <button class="btn" onclick="cvV26Print('C')">🖨️ Imprimir C</button>
          <button class="btn" onclick="cvV26Print('G')">🔑 Gabaritos</button>
        </div>
        <div id="v24Info"></div><div id="v24Preview"></div>
      </div>`;
    document.body.appendChild(sec);
    ["v24Ano","v24Bim","v24Disc","v24Dif"].forEach(id=>$(id)?.addEventListener("change",cvV26Refresh));
    cvV26Refresh();
  };
  window.cvV26Refresh=function(){
    const n=filtered().length, el=$("v26BankStatus");
    if(el) el.innerHTML=`✔ <b>${n} questões encontradas</b> para ${esc($("v24Ano")?.value)} • ${esc($("v24Disc")?.value)} • ${esc($("v24Bim")?.value)}${$("v24Dif")?.value?" • "+esc($("v24Dif").value):""}.`;
  };
  function makeVersions(){
    const qtd=Number($("v24Qtd").value), base=filtered().map(normalize);
    if(base.length<qtd) return null;
    const chosen=shuffle(base).slice(0,qtd), versions={};
    ["A","B","C"].forEach(l=>versions[l]=shuffle(chosen).map(q=>{
      const ops=shuffle(q.alternativas.map((text,i)=>({text,i})));
      return {...q,alternativas:ops.map(x=>x.text),gabarito:ops.findIndex(x=>x.i===q.gabarito)};
    }));
    return {id:"AV-"+Date.now(),ano:$("v24Ano").value,bimestre:$("v24Bim").value,disciplina:$("v24Disc").value,
      quantidade:qtd,dificuldade:$("v24Dif").value,escola:$("v24Esc").value,turma:$("v24Turma").value,
      professor:$("v24Prof").value,versions,createdAt:new Date().toLocaleString("pt-BR")};
  }
  function paper(letter){
    const d=window.cvV24Current, arr=d?.versions?.[letter]; if(!arr)return "";
    return `<div class="v24-paper"><header><h1>${esc(d.escola||"CARNEIROS VIRTUAL")}</h1><h2>AVALIAÇÃO — ${esc(d.disciplina)}</h2><p>${esc(d.ano)} • ${esc(d.bimestre)} • Versão ${letter}</p><p>Aluno(a): ________________________________________________</p><p>Turma: ${esc(d.turma)} &nbsp; Professor(a): ${esc(d.professor)}</p></header>`+
      arr.map((q,i)=>`<div class="v24-q"><b>${i+1}. ${esc(q.questao)}</b>${q.alternativas.map((a,j)=>`<div>${String.fromCharCode(65+j)}) ${esc(a)}</div>`).join("")}</div>`).join("")+
      `<footer>CarneirosVirtual.com • Professor Antônio</footer></div>`;
  }
  function gabs(){const d=window.cvV24Current;return ["A","B","C"].map(l=>`<div class="v24-g"><h2>GABARITO — VERSÃO ${l}</h2>${d.versions[l].map((q,i)=>`${i+1}. <b>${String.fromCharCode(65+q.gabarito)}</b>`).join(" &nbsp; | &nbsp; ")}</div>`).join("")}
  window.cvV26Generate=function(){
    const d=makeVersions();
    if(!d){$("v24Info").innerHTML=`<div class="alert">Não foi possível gerar. O filtro atual possui <b>${filtered().length}</b> questões, mas você pediu <b>${$("v24Qtd").value}</b>.</div>`;return}
    window.cvV24Current=d;
    $("v24Info").innerHTML='<div class="success">✔ Avaliação gerada com sucesso. As três versões têm questões e alternativas embaralhadas.</div>';
    $("v24Preview").innerHTML=`<div class="tabs"><button class="btn" onclick="v26Show('A')">Versão A</button><button class="btn" onclick="v26Show('B')">Versão B</button><button class="btn" onclick="v26Show('C')">Versão C</button><button class="btn" onclick="v26Show('G')">Gabaritos</button></div><div id="v24Show">${paper("A")}</div>`;
  };
  window.v26Show=l=>{$("v24Show").innerHTML=l==="G"?gabs():paper(l)};
  function saved(){try{return JSON.parse(localStorage.getItem("cv_avaliacoes_v24")||"[]")}catch(e){return[]}}
  window.cvV26Save=function(){if(!window.cvV24Current){alert("Gere uma avaliação primeiro.");return}const a=saved();a.push(window.cvV24Current);localStorage.setItem("cv_avaliacoes_v24",JSON.stringify(a));alert("Avaliação salva.")};
  window.cvV26List=function(){const a=saved();$("v24Preview").innerHTML=a.length?a.map((x,i)=>`<div class="card"><b>${esc(x.id)}</b> — ${esc(x.ano)} — ${esc(x.disciplina)} — ${esc(x.bimestre)}<br><button class="btn" onclick="window.cvV24Current=JSON.parse(localStorage.getItem('cv_avaliacoes_v24'))[${i}];document.getElementById('v24Preview').innerHTML='<div id=&quot;v24Show&quot;>'+v26Show('A')+'</div>'">Abrir</button></div>`).join(""):"<p>Nenhuma avaliação salva.</p>"};
  window.cvV26Print=function(l){
    if(!window.cvV24Current){alert("Gere ou abra uma avaliação.");return}
    const body=l==="G"?gabs():paper(l),w=window.open("","_blank");if(!w)return;
    w.document.write(`<html><head><title>Carneiros Virtual — Avaliação</title><style>@page{size:A4 portrait;margin:12mm}body{font-family:Arial;color:#111}.v24-q{margin:14px 0;line-height:1.5}.v24-g{page-break-after:always;font-size:18px;line-height:2}</style></head><body>${body}</body></html>`);
    w.document.close();w.focus();setTimeout(()=>w.print(),300);
  };
})();


/* =========================================================
   V27 — AVALIAÇÃO INTEGRADA + DIÁRIO DE NOTAS
   Integra geração de prova ao cadastro escolar da V25.
   ========================================================= */
(function(){
 const $=id=>document.getElementById(id);
 const esc=s=>String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":">","\"":"&quot;","'":"&#39;"}[m]));
 const KEY="cv_diario_notas_v27";
 const read=()=>{try{return JSON.parse(localStorage.getItem(KEY)||"[]")}catch(e){return[]}};
 const write=x=>localStorage.setItem(KEY,JSON.stringify(x));
 const school=()=>{try{return JSON.parse(localStorage.getItem("cv_gestao_v25")||"{}")}catch(e){return{}}};

 window.cvV27UI=function(){
  if($("avaliacaoIntegradaV27")) return;
  const s=document.createElement("section");s.id="avaliacaoIntegradaV27";s.className="page-section";
  s.innerHTML=`
  <div class="card">
   <h2>🔗 Avaliação Integrada e Diário de Notas</h2>
   <p>Gere uma avaliação a partir do banco de questões e registre automaticamente os resultados dos alunos.</p>
   <div class="grid">
    <label>Ano/Etapa<select id="v27Ano"></select></label>
    <label>Bimestre<select id="v27Bim"><option>1º bimestre</option><option>2º bimestre</option><option>3º bimestre</option><option>4º bimestre</option></select></label>
    <label>Disciplina<select id="v27Disc"></select></label>
    <label>Quantidade<select id="v27Qtd"><option>10</option><option>15</option><option>20</option><option>25</option></select></label>
    <label>Turma<select id="v27Turma"><option value="">Selecione</option></select></label>
    <label>Valor da avaliação<input id="v27Valor" type="number" min="0" max="10" step="0.1" value="10"></label>
   </div>
   <div id="v27Status" class="success">Carregando banco...</div>
   <div class="actions">
    <button class="btn primary" onclick="cvV27Generate()">🎲 Gerar avaliação</button>
    <button class="btn" onclick="cvV27Apply()">📋 Preparar lançamento</button>
    <button class="btn" onclick="cvV27Report()">📊 Relatório da turma</button>
    <button class="btn" onclick="cvV27Print()">🖨️ Imprimir</button>
   </div>
   <div id="v27Preview"></div>
   <div id="v27Launch"></div>
  </div>`;
  document.body.appendChild(s); cvV27Load();
 };

 function bank(){
  const b=window.CV_QUESTOES_BIMESTRAIS||{};let out=[];
  Object.keys(b).forEach(ano=>Object.keys(b[ano]||{}).forEach(d=>Object.keys(b[ano][d]||{}).forEach(bim=>{
   (b[ano][d][bim]||[]).forEach(q=>out.push({...q,ano,disciplina:d,bimestre:bim}));
  })));return out;
 }
 function cvV27Load(){
  const all=bank(), anos=[...new Set(all.map(q=>q.ano))], discs=[...new Set(all.map(q=>q.disciplina))];
  $("v27Ano").innerHTML=anos.map(x=>`<option>${esc(x)}</option>`).join("");
  $("v27Disc").innerHTML=discs.map(x=>`<option>${esc(x)}</option>`).join("");
  const g=school();$("v27Turma").innerHTML=`<option value="">Selecione</option>`+(g.turmas||[]).map(x=>`<option value="${x.id}">${esc(x.nome)}</option>`).join("");
  ["v27Ano","v27Bim","v27Disc"].forEach(id=>$(id).addEventListener("change",cvV27Count));
  cvV27Count();
 }
 function current(){
  return bank().filter(q=>q.ano===$("v27Ano").value&&q.disciplina===$("v27Disc").value&&q.bimestre===$("v27Bim").value);
 }
 function cvV27Count(){
  if(!$("v27Status"))return;
  $("v27Status").innerHTML=`✔ <b>${current().length} questões encontradas</b> para ${esc($("v27Ano").value)} • ${esc($("v27Disc").value)} • ${esc($("v27Bim").value)}.`;
 }
 function shuffle(a){return a.map(x=>[Math.random(),x]).sort((a,b)=>a[0]-b[0]).map(x=>x[1])}
 window.cvV27Generate=function(){
  const n=+$("v27Qtd").value, arr=current();
  if(arr.length<n){$("v27Status").className="alert";$("v27Status").innerHTML=`Há ${arr.length} questões disponíveis; escolha no máximo ${arr.length}.`;return}
  const chosen=shuffle(arr).slice(0,n);
  window.cvV27Current={id:"PROVA-"+Date.now(),ano:$("v27Ano").value,bimestre:$("v27Bim").value,disciplina:$("v27Disc").value,turma:$("v27Turma").value,valor:+$("v27Valor").value,questions:chosen};
  $("v27Preview").innerHTML=`<div class="success">✔ Prova criada com <b>${n} questões</b>. Cada questão vale ${(+$("v27Valor").value/n).toFixed(2)} ponto(s).</div>`+
   `<div class="card"><h3>${esc(window.cvV27Current.disciplina)} — ${esc(window.cvV27Current.ano)}</h3>`+
   chosen.map((q,i)=>`<div class="v24-q"><b>${i+1}. ${esc(q.questao)}</b>${(q.alternativas||[]).map((a,j)=>`<div>${String.fromCharCode(65+j)}) ${esc(a)}</div>`).join("")}</div>`).join("")+"</div>";
 };
 window.cvV27Apply=function(){
  const d=window.cvV27Current,g=school();
  if(!d){alert("Gere a avaliação primeiro.");return}
  const alunos=(g.alunos||[]).filter(a=>!d.turma||a.turma===d.turma);
  if(!alunos.length){alert("Não há alunos cadastrados para esta turma.");return}
  $("v27Launch").innerHTML=`<h3>📋 Lançar resultados</h3><p>Digite a nota de cada aluno (0 a ${d.valor}).</p>`+
   `<div class="v25-table"><table><thead><tr><th>Aluno</th><th>Nota</th><th>Frequência (%)</th></tr></thead><tbody>`+
   alunos.map(a=>`<tr><td>${esc(a.nome)}</td><td><input class="v27Nota" data-aluno="${a.id}" type="number" min="0" max="${d.valor}" step="0.1"></td><td><input class="v27Freq" data-aluno="${a.id}" type="number" min="0" max="100" value="100"></td></tr>`).join("")+
   `</tbody></table></div><button class="btn primary" onclick="cvV27SaveResults()">💾 Salvar resultados</button>`;
 };
 window.cvV27SaveResults=function(){
  const d=window.cvV27Current,g=school(), notas=read(), inputs=[...document.querySelectorAll(".v27Nota")];
  inputs.forEach(inp=>{
   const aluno=inp.dataset.aluno, nota=parseFloat(inp.value);
   if(!isNaN(nota)){
    const fr=parseFloat(document.querySelector('.v27Freq[data-aluno="'+aluno+'"]')?.value||100);
    notas.push({id:"N-"+Date.now()+"-"+Math.random().toString(36).slice(2,6),aluno,disciplina:d.disciplina,bimestre:d.bimestre,nota,frequencia:fr,avaliacao:d.id,data:new Date().toISOString()});
   }
  });
  write(notas);alert("Resultados salvos no Diário de Notas.");cvV27Report();
 };
 window.cvV27Report=function(){
  const d=window.cvV27Current;if(!d){alert("Gere uma avaliação primeiro.");return}
  const g=school(), notas=read().filter(n=>n.avaliacao===d.id);
  const rows=notas.map(n=>`<tr><td>${esc((g.alunos||[]).find(a=>a.id===n.aluno)?.nome||n.aluno)}</td><td>${n.nota.toFixed(1)}</td><td>${n.frequencia}%</td><td>${n.nota>=d.valor*0.6&&n.frequencia>=75?"Aprovado":"Acompanhar"}</td></tr>`).join("");
  $("v27Launch").innerHTML=`<h3>📊 Relatório da avaliação ${esc(d.id)}</h3><div class="v25-table"><table><thead><tr><th>Aluno</th><th>Nota</th><th>Freq.</th><th>Situação</th></tr></thead><tbody>${rows||"<tr><td colspan=4>Nenhum resultado lançado.</td></tr>"}</tbody></table></div>`;
 };
 window.cvV27Print=function(){
  if(!window.cvV27Current){alert("Gere uma avaliação.");return}
  const d=window.cvV27Current,w=window.open("","_blank");if(!w)return;
  const html=$("v27Preview").innerHTML.replace(/<button[\s\S]*?<\/button>/gi,"");
  w.document.write(`<html><head><title>Carneiros Virtual — Avaliação</title><style>@page{size:A4 portrait;margin:12mm}body{font-family:Arial;color:#111}.v24-q{margin:14px 0;line-height:1.5}header{text-align:center}</style></head><body><header><h1>CARNEIROS VIRTUAL</h1><h2>AVALIAÇÃO</h2><p>${esc(d.ano)} • ${esc(d.disciplina)} • ${esc(d.bimestre)}</p><p>Aluno(a): __________________________________________</p></header>${html}</body></html>`);
  w.document.close();w.focus();setTimeout(()=>w.print(),300);
 };
 function nav(){
  const n=$("nav")||document.querySelector(".nav");if(n&&!$("navV27")){
   const b=document.createElement("button");b.id="navV27";b.className="nav-btn";b.textContent="🔗 • Avaliação Integrada";
   b.onclick=()=>{cvV27UI();document.querySelectorAll("section").forEach(s=>s.style.display="none");$("avaliacaoIntegradaV27").style.display="block"};
   n.appendChild(b);
  }
 }
 document.addEventListener("DOMContentLoaded",()=>setTimeout(nav,700));
})();


/* V28 - BOTAO VOLTAR AO INICIO */
(function(){
 function home(){
  try{
   var h=document.getElementById('inicio');
   if(typeof window.go==='function'){try{window.go('inicio',document.querySelector('#nav button[onclick*="inicio"]'));}catch(e){}}
   if(h){document.querySelectorAll('section').forEach(function(s){s.style.display=s===h?'block':'none';});}
   window.scrollTo({top:0,left:0,behavior:'smooth'});
   setTimeout(function(){window.scrollTo(0,0);},500);
  }catch(e){window.scrollTo(0,0)}
 }
 function install(){
  var old=document.getElementById('backToTop')||document.getElementById('btnInicio')||document.querySelector('.back-to-top');
  var b=old||document.createElement('button');
  b.id='cvV28BackTop'; b.type='button'; b.className='cv-v28-back-top';
  b.setAttribute('aria-label','Voltar ao inicio'); b.title='Voltar ao inicio'; b.textContent='↑';
  if(!b.parentNode) document.body.appendChild(b);
  var n=b.cloneNode(true); b.parentNode.replaceChild(n,b);
  n.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();home();},true);
 }
 document.addEventListener('DOMContentLoaded',function(){setTimeout(install,800);});
 window.cvV28GoHome=home;
})();
